tools.exec_command({cmd:"wt --version; wt step prune --dry-run; git worktree list","max_output_tokens":2500}),
tools.exec_command({cmd:"git status --short; wt list --format=json | python3 -c 'import sys,json; d=json.load(sys.stdin); print(json.dumps(d,indent=2))'","max_output_tokens":4000})
]);r.forEach(text);

